sc_pkcs15_decode_pubkey_ec(sc_context_t *ctx,
                struct sc_pkcs15_pubkey_ec *key,
                const u8 *buf, size_t buflen)
{
        int r;
        u8 * ecpoint_data;
        size_t ecpoint_len;
        struct sc_asn1_entry asn1_ec_pointQ[C_ASN1_EC_POINTQ_SIZE];

        LOG_FUNC_CALLED(ctx);
        sc_copy_asn1_entry(c_asn1_ec_pointQ, asn1_ec_pointQ);
        sc_format_asn1_entry(asn1_ec_pointQ + 0, &ecpoint_data, &ecpoint_len, 1);
        r = sc_asn1_decode(ctx, asn1_ec_pointQ, buf, buflen, NULL, NULL);
        if (r < 0)
                LOG_TEST_RET(ctx, r, "ASN.1 decoding failed");

        if (*ecpoint_data != 0x04)
                LOG_TEST_RET(ctx, SC_ERROR_NOT_SUPPORTED, "Supported only uncompressed EC pointQ value");

        key->ecpointQ.len = ecpoint_len;
        key->ecpointQ.value = ecpoint_data;

        /*
         * Only get here if raw point is stored in pkcs15 without curve name
         * spki has the curvename, so we can get the field_length
         * Following only true for curves that are multiple of 8
         */
        key->params.field_length = (ecpoint_len - 1)/2 * 8;
        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}


int
sc_pkcs15_encode_pubkey_ec(sc_context_t *ctx, struct sc_pkcs15_pubkey_ec *key,
                u8 **buf, size_t *buflen)
{
        struct sc_asn1_entry asn1_ec_pointQ[C_ASN1_EC_POINTQ_SIZE];

        LOG_FUNC_CALLED(ctx);
        sc_copy_asn1_entry(c_asn1_ec_pointQ, asn1_ec_pointQ);
        sc_format_asn1_entry(asn1_ec_pointQ + 0, key->ecpointQ.value, &key->ecpointQ.len, 1);

        LOG_FUNC_RETURN(ctx,
                        sc_asn1_encode(ctx, asn1_ec_pointQ, buf, buflen));
}


int
sc_pkcs15_encode_pubkey(sc_context_t *ctx, struct sc_pkcs15_pubkey *key,
                u8 **buf, size_t *len)
{
        if (key->algorithm == SC_ALGORITHM_RSA)
                return sc_pkcs15_encode_pubkey_rsa(ctx, &key->u.rsa, buf, len);
        if (key->algorithm == SC_ALGORITHM_DSA)
                return sc_pkcs15_encode_pubkey_dsa(ctx, &key->u.dsa, buf, len);
        if (key->algorithm == SC_ALGORITHM_GOSTR3410)
                return sc_pkcs15_encode_pubkey_gostr3410(ctx, &key->u.gostr3410, buf, len);
        if (key->algorithm == SC_ALGORITHM_EC)
                return sc_pkcs15_encode_pubkey_ec(ctx, &key->u.ec, buf, len);

        sc_log(ctx, "Encoding of public key type %u not supported", key->algorithm);
        LOG_FUNC_RETURN(ctx, SC_ERROR_NOT_SUPPORTED);
}


static const struct sc_asn1_entry       c_asn1_spki_key_items[] = {
                { "algorithm",  SC_ASN1_ALGORITHM_ID, SC_ASN1_CONS| SC_ASN1_TAG_SEQUENCE, 0, NULL, NULL},
                { "key",        SC_ASN1_BIT_STRING_NI, SC_ASN1_TAG_BIT_STRING, 0, NULL, NULL },
                { NULL, 0, 0, 0, NULL, NULL }
};

static const struct sc_asn1_entry       c_asn1_spki_key[] = {
                { "publicKey",  SC_ASN1_STRUCT, SC_ASN1_CONS | SC_ASN1_TAG_SEQUENCE, 0, NULL, NULL},
                { NULL, 0, 0, 0, NULL, NULL }
};

/*
 * Encode a pubkey as a SPKI, useful for pkcs15-tool, and for PKCS#15 files.
 */
int
sc_pkcs15_encode_pubkey_as_spki(sc_context_t *ctx, struct sc_pkcs15_pubkey *pubkey,
                u8 **buf, size_t *len)
{
        int r = 0;
        struct sc_asn1_entry  asn1_spki_key[2], asn1_spki_key_items[3];
        struct sc_pkcs15_u8 pkey;
        size_t key_len;

        LOG_FUNC_CALLED(ctx);
        pkey.value =  NULL;
        pkey.len = 0;

        sc_log(ctx, "Encoding public key with algorithm %i", pubkey->algorithm);
        if (!pubkey->alg_id)   {
                pubkey->alg_id = calloc(1, sizeof(struct sc_algorithm_id));
                if (!pubkey->alg_id)
                        LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);

                sc_init_oid(&pubkey->alg_id->oid);
                pubkey->alg_id->algorithm = pubkey->algorithm;
        }

        switch (pubkey->algorithm) {
        case SC_ALGORITHM_EC:
                /*
                 * most keys, but not EC have only one encoding.
                 * For a SPKI, the ecpoint is placed directly in the
                 * BIT STRING
                 */
                key_len = pubkey->u.ec.ecpointQ.len * 8;
                pkey.value = pubkey->u.ec.ecpointQ.value;
                pkey.len = 0; /* flag as do not delete */

                if (pubkey->u.ec.params.named_curve || pubkey->u.ec.params.der.value)   {
                        struct sc_ec_parameters *ec_params = NULL;

                        r = sc_pkcs15_fix_ec_parameters(ctx, &pubkey->u.ec.params);
                        LOG_TEST_RET(ctx, r, "failed to fix EC parameters");

                        ec_params  = calloc(1, sizeof(struct sc_ec_parameters));
                        if (!ec_params)
                                LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
                        ec_params->type = 1;
                        ec_params->der.value = calloc(pubkey->u.ec.params.der.len, 1);
                        if (!ec_params->der.value) {
                                free(ec_params);
                                LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
                        }
                        memcpy(ec_params->der.value, pubkey->u.ec.params.der.value, pubkey->u.ec.params.der.len);
                        ec_params->der.len = pubkey->u.ec.params.der.len;
                        /* This could have been already allocated: avoid memory leak */
                        sc_asn1_clear_algorithm_id(pubkey->alg_id);
                        pubkey->alg_id->params = ec_params;
                }
                break;
        case SC_ALGORITHM_GOSTR3410:
                /* TODO is this needed?  does it cause mem leak? */
                pubkey->alg_id->params = &pubkey->u.gostr3410.params;
                r = sc_pkcs15_encode_pubkey(ctx, pubkey, &pkey.value, &pkey.len);
                key_len = pkey.len * 8;
                break;
        default:
                r = sc_pkcs15_encode_pubkey(ctx, pubkey, &pkey.value, &pkey.len);
                key_len = pkey.len * 8;
                break;
        }

        if (r == 0) {
                sc_copy_asn1_entry(c_asn1_spki_key, asn1_spki_key);
                sc_copy_asn1_entry(c_asn1_spki_key_items, asn1_spki_key_items);
                sc_format_asn1_entry(asn1_spki_key + 0, asn1_spki_key_items, NULL, 1);
                sc_format_asn1_entry(asn1_spki_key_items + 0, pubkey->alg_id, NULL, 1);
                sc_format_asn1_entry(asn1_spki_key_items + 1, pkey.value, &key_len, 1);

                r =  sc_asn1_encode(ctx, asn1_spki_key, buf, len);
        }

        if (pkey.len && pkey.value)
                free(pkey.value);

        LOG_FUNC_RETURN(ctx, r);
}


int

sc_pkcs15_decode_pubkey_rsa(sc_context_t *ctx, struct sc_pkcs15_pubkey_rsa *key,
                const u8 *buf, size_t buflen)
{
        struct sc_asn1_entry asn1_public_key[C_ASN1_PUBLIC_KEY_SIZE];
        struct sc_asn1_entry asn1_rsa_pub_coefficients[C_ASN1_RSA_PUB_COEFFICIENTS_SIZE];
        int r;

        LOG_FUNC_CALLED(ctx);
        sc_copy_asn1_entry(c_asn1_public_key, asn1_public_key);
        sc_format_asn1_entry(asn1_public_key + 0, asn1_rsa_pub_coefficients, NULL, 0);

        sc_copy_asn1_entry(c_asn1_rsa_pub_coefficients, asn1_rsa_pub_coefficients);
        sc_format_asn1_entry(asn1_rsa_pub_coefficients + 0, &key->modulus.data, &key->modulus.len, 0);
        sc_format_asn1_entry(asn1_rsa_pub_coefficients + 1, &key->exponent.data, &key->exponent.len, 0);

        r = sc_asn1_decode(ctx, asn1_public_key, buf, buflen, NULL, NULL);
        LOG_TEST_RET(ctx, r, "ASN.1 parsing of public key failed");

        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}


int
sc_pkcs15_encode_pubkey_rsa(sc_context_t *ctx, struct sc_pkcs15_pubkey_rsa *key,
                u8 **buf, size_t *buflen)
{
        struct sc_asn1_entry asn1_public_key[C_ASN1_PUBLIC_KEY_SIZE];
        struct sc_asn1_entry asn1_rsa_pub_coefficients[C_ASN1_RSA_PUB_COEFFICIENTS_SIZE];
        int r;

        LOG_FUNC_CALLED(ctx);
        sc_copy_asn1_entry(c_asn1_public_key, asn1_public_key);
        sc_format_asn1_entry(asn1_public_key + 0, asn1_rsa_pub_coefficients, NULL, 1);

        sc_copy_asn1_entry(c_asn1_rsa_pub_coefficients, asn1_rsa_pub_coefficients);
        sc_format_asn1_entry(asn1_rsa_pub_coefficients + 0, key->modulus.data, &key->modulus.len, 1);
        sc_format_asn1_entry(asn1_rsa_pub_coefficients + 1, key->exponent.data, &key->exponent.len, 1);

        r = sc_asn1_encode(ctx, asn1_public_key, buf, buflen);
        LOG_TEST_RET(ctx, r, "ASN.1 encoding failed");

        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}


int

int sc_pkcs15_parse_tokeninfo(sc_context_t *ctx,
        sc_pkcs15_tokeninfo_t *ti, const u8 *buf, size_t blen)
{
        int r;
        size_t ii;
        u8 serial[128];
        size_t serial_len = sizeof(serial);
        u8 mnfid[SC_PKCS15_MAX_LABEL_SIZE];
        size_t mnfid_len  = sizeof(mnfid) - 1;
        u8 label[SC_PKCS15_MAX_LABEL_SIZE];
        size_t label_len = sizeof(label) - 1;
        u8 last_update[32], profile_indication[SC_PKCS15_MAX_LABEL_SIZE];
        size_t lupdate_len = sizeof(last_update) - 1, pi_len = sizeof(profile_indication) - 1;
        size_t flags_len   = sizeof(ti->flags);
        u8 preferred_language[3];
        size_t lang_length = sizeof(preferred_language);
        struct sc_asn1_entry asn1_supported_algorithms[SC_MAX_SUPPORTED_ALGORITHMS + 1],
                        asn1_algo_infos[SC_MAX_SUPPORTED_ALGORITHMS][7],
                        asn1_algo_infos_parameters[SC_MAX_SUPPORTED_ALGORITHMS][3];
        size_t reference_len = sizeof(ti->supported_algos[0].reference);
        size_t mechanism_len = sizeof(ti->supported_algos[0].mechanism);
        size_t parameter_len = sizeof(ti->supported_algos[0].parameters);
        size_t operations_len = sizeof(ti->supported_algos[0].operations);
        size_t algo_ref_len = sizeof(ti->supported_algos[0].algo_ref);

        struct sc_asn1_entry asn1_last_update[C_ASN1_LAST_UPDATE_SIZE];
        struct sc_asn1_entry asn1_profile_indication[C_ASN1_PROFILE_INDICATION_SIZE];
        struct sc_asn1_entry asn1_toki_attrs[C_ASN1_TOKI_ATTRS_SIZE], asn1_tokeninfo[3], asn1_twlabel[3];

        memset(last_update, 0, sizeof(last_update));
        memset(label, 0, sizeof(label));
        memset(profile_indication, 0, sizeof(profile_indication));
        memset(mnfid, 0, sizeof(mnfid));

        sc_copy_asn1_entry(c_asn1_twlabel, asn1_twlabel);
        sc_copy_asn1_entry(c_asn1_toki_attrs, asn1_toki_attrs);
        sc_copy_asn1_entry(c_asn1_tokeninfo, asn1_tokeninfo);
        sc_copy_asn1_entry(c_asn1_last_update, asn1_last_update);
        sc_format_asn1_entry(asn1_twlabel, label, &label_len, 0);
        sc_copy_asn1_entry(c_asn1_profile_indication, asn1_profile_indication);

        for (ii=0; ii<SC_MAX_SUPPORTED_ALGORITHMS; ii++) {
                sc_copy_asn1_entry(c_asn1_algorithm_info, asn1_algo_infos[ii]);
                sc_copy_asn1_entry(c_asn1_algorithm_info_parameters,
                        asn1_algo_infos_parameters[ii]);
        }
        sc_copy_asn1_entry(c_asn1_supported_algorithms, asn1_supported_algorithms);

        for (ii=0; ii<SC_MAX_SUPPORTED_ALGORITHMS; ii++)   {
                sc_format_asn1_entry(asn1_algo_infos[ii] + 0, &ti->supported_algos[ii].reference, &reference_len, 0);
                sc_format_asn1_entry(asn1_algo_infos[ii] + 1, &ti->supported_algos[ii].mechanism, &mechanism_len, 0);
                sc_format_asn1_entry(asn1_algo_infos[ii] + 2,
                        asn1_algo_infos_parameters[ii], NULL, 0);
                sc_format_asn1_entry(asn1_algo_infos_parameters[ii] + 0,
                        NULL, NULL, 0);
                sc_format_asn1_entry(asn1_algo_infos_parameters[ii] + 1,
                        &ti->supported_algos[ii].parameters, &parameter_len, 0);
                sc_format_asn1_entry(asn1_algo_infos[ii] + 3, &ti->supported_algos[ii].operations, &operations_len, 0);
                sc_format_asn1_entry(asn1_algo_infos[ii] + 4, &ti->supported_algos[ii].algo_id, NULL, 1);
                sc_format_asn1_entry(asn1_algo_infos[ii] + 5, &ti->supported_algos[ii].algo_ref, &algo_ref_len, 0);
                sc_format_asn1_entry(asn1_supported_algorithms + ii, asn1_algo_infos[ii], NULL, 0);
        }

        sc_format_asn1_entry(asn1_last_update + 0, last_update, &lupdate_len, 0);
        sc_format_asn1_entry(asn1_last_update + 1, &ti->last_update.path, NULL, 0);

        sc_format_asn1_entry(asn1_profile_indication + 0, &ti->profile_indication.oid, NULL, 0);
        sc_format_asn1_entry(asn1_profile_indication + 1, profile_indication, &pi_len, 0);

        sc_format_asn1_entry(asn1_toki_attrs + 0, &ti->version, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 1, serial, &serial_len, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 2, mnfid, &mnfid_len, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 3, label, &label_len, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 4, asn1_twlabel, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 5, &ti->flags, &flags_len, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 6, &ti->seInfo, &ti->num_seInfo, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 7, NULL, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 8, asn1_supported_algorithms, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 9, NULL, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 10, NULL, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 11, asn1_last_update, NULL, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 12, preferred_language, &lang_length, 0);
        sc_format_asn1_entry(asn1_toki_attrs + 13, asn1_profile_indication, NULL, 0);
        sc_format_asn1_entry(asn1_tokeninfo, asn1_toki_attrs, NULL, 0);

        r = sc_asn1_decode(ctx, asn1_tokeninfo, buf, blen, NULL, NULL);
        LOG_TEST_RET(ctx, r, "ASN.1 parsing of EF(TokenInfo) failed");

        if (asn1_toki_attrs[1].flags & SC_ASN1_PRESENT && serial_len > 0)   {
                ti->serial_number = malloc(serial_len * 2 + 1);
                if (ti->serial_number == NULL)
                        return SC_ERROR_OUT_OF_MEMORY;
                sc_bin_to_hex(serial, serial_len, ti->serial_number, serial_len * 2 + 1, 0);
                sc_log(ctx, "TokenInfo.serialNunmber '%s'", ti->serial_number);
        }

        if (ti->manufacturer_id == NULL) {
                if (asn1_toki_attrs[2].flags & SC_ASN1_PRESENT)
                        ti->manufacturer_id = strdup((char *) mnfid);
                else
                        ti->manufacturer_id = strdup("(unknown)");
                if (ti->manufacturer_id == NULL)
                        return SC_ERROR_OUT_OF_MEMORY;
        }
        if (ti->label == NULL) {
                if (asn1_toki_attrs[3].flags & SC_ASN1_PRESENT ||
                    asn1_toki_attrs[4].flags & SC_ASN1_PRESENT)
                        ti->label = strdup((char *) label);
                else
                        ti->label = strdup("(unknown)");
                if (ti->label == NULL)
                        return SC_ERROR_OUT_OF_MEMORY;
        }
        if (asn1_toki_attrs[11].flags & SC_ASN1_PRESENT) {
                if (asn1_last_update[0].flags & SC_ASN1_PRESENT)   {
                        sc_log(ctx, "LastUpdate.generalizedTime present");
                        ti->last_update.gtime = strdup((char *)last_update);

sc_asn1_sig_value_rs_to_sequence(struct sc_context *ctx, unsigned char *in, size_t inlen,
                unsigned char **buf, size_t *buflen)
{
        struct sc_asn1_entry asn1_sig_value[C_ASN1_SIG_VALUE_SIZE];
        struct sc_asn1_entry asn1_sig_value_coefficients[C_ASN1_SIG_VALUE_COEFFICIENTS_SIZE];
        unsigned char *r = in, *s = in + inlen/2;
        size_t r_len = inlen/2, s_len = inlen/2;
        int rv;

        LOG_FUNC_CALLED(ctx);

        /* R/S are filled up with zeroes, we do not want that in sequence format */
        while(r_len > 1 && *r == 0x00) {
                r++;
                r_len--;
        }
        while(s_len > 1 && *s == 0x00) {
                s++;
                s_len--;
        }

        sc_copy_asn1_entry(c_asn1_sig_value, asn1_sig_value);
        sc_format_asn1_entry(asn1_sig_value + 0, asn1_sig_value_coefficients, NULL, 1);

        sc_copy_asn1_entry(c_asn1_sig_value_coefficients, asn1_sig_value_coefficients);
        sc_format_asn1_entry(asn1_sig_value_coefficients + 0, r, &r_len, 1);
        sc_format_asn1_entry(asn1_sig_value_coefficients + 1, s, &s_len, 1);

        rv = sc_asn1_encode(ctx, asn1_sig_value, buf, buflen);
        LOG_TEST_RET(ctx, rv, "ASN.1 encoding ECDSA-SIg-Value failed");

        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}


int
sc_asn1_sig_value_sequence_to_rs(struct sc_context *ctx, const unsigned char *in, size_t inlen,
                unsigned char *buf, size_t buflen)
{
        struct sc_asn1_entry asn1_sig_value[C_ASN1_SIG_VALUE_SIZE];
        struct sc_asn1_entry asn1_sig_value_coefficients[C_ASN1_SIG_VALUE_COEFFICIENTS_SIZE];
        unsigned char *r = NULL, *s = NULL;
        size_t r_len = 0, s_len = 0, halflen = buflen/2;
        int rv;

        LOG_FUNC_CALLED(ctx);
        if (!buf || !buflen)
                LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);

        sc_copy_asn1_entry(c_asn1_sig_value, asn1_sig_value);
        sc_format_asn1_entry(asn1_sig_value + 0, asn1_sig_value_coefficients, NULL, 0);

        sc_copy_asn1_entry(c_asn1_sig_value_coefficients, asn1_sig_value_coefficients);
        sc_format_asn1_entry(asn1_sig_value_coefficients + 0, &r, &r_len, 0);
        sc_format_asn1_entry(asn1_sig_value_coefficients + 1, &s, &s_len, 0);

        rv = sc_asn1_decode(ctx, asn1_sig_value, in, inlen, NULL, NULL);
        LOG_TEST_GOTO_ERR(ctx, rv, "ASN.1 decoding ECDSA-Sig-Value failed");

        if (halflen < r_len || halflen < s_len)   {
                rv = SC_ERROR_BUFFER_TOO_SMALL;
                goto err;
        }

        memset(buf, 0, buflen);
        if (r_len > 0)
                memcpy(buf + (halflen - r_len), r, r_len);
        if (s_len > 0)
                memcpy(buf + (buflen - s_len), s, s_len);

        sc_log(ctx, "r(%"SC_FORMAT_LEN_SIZE_T"u): %s", halflen,
               sc_dump_hex(buf, halflen));
        sc_log(ctx, "s(%"SC_FORMAT_LEN_SIZE_T"u): %s", halflen,
               sc_dump_hex(buf + halflen, halflen));

        rv = SC_SUCCESS;
err:
        free(r);
        free(s);

        LOG_FUNC_RETURN(ctx, rv);
}

int sc_asn1_decode(sc_context_t *ctx, struct sc_asn1_entry *asn1,
                   const u8 *in, size_t len, const u8 **newp, size_t *len_left)
{
        return asn1_decode(ctx, asn1, in, len, newp, len_left, 0, 0);
}

int sc_asn1_decode_choice(sc_context_t *ctx, struct sc_asn1_entry *asn1,
                          const u8 *in, size_t len, const u8 **newp, size_t *len_left)
{
        return asn1_decode(ctx, asn1, in, len, newp, len_left, 1, 0);
}

static int asn1_encode_entry(sc_context_t *ctx, const struct sc_asn1_entry *entry,
                             u8 **obj, size_t *objlen, int depth)
{
        void *parm = entry->parm;
        int (*callback_func)(sc_context_t *nctx, void *arg, u8 **nobj,
                             size_t *nobjlen, int ndepth);
        const size_t *len = (const size_t *) entry->arg;
        int r = 0;
        u8 * buf = NULL;
        size_t buflen = 0;

        callback_func = parm;

        sc_debug(ctx, SC_LOG_DEBUG_ASN1, "%*.*sencoding '%s'%s\n",
                depth, depth, "", entry->name,
                (entry->flags & SC_ASN1_PRESENT)? "" : " (not present)");
        if (!(entry->flags & SC_ASN1_PRESENT))
                goto no_object;
        sc_debug(ctx, SC_LOG_DEBUG_ASN1,
                 "%*.*stype=%d, tag=0x%02x, parm=%p, len=%"SC_FORMAT_LEN_SIZE_T"u\n",
                 depth, depth, "", entry->type, entry->tag, parm,
                 len ? *len : 0);

        if (entry->type == SC_ASN1_CHOICE) {
                const struct sc_asn1_entry *list, *choice = NULL;

                list = (const struct sc_asn1_entry *) parm;
                while (list->name != NULL) {
                        if (list->flags & SC_ASN1_PRESENT) {
                                if (choice) {
                                        sc_debug(ctx, SC_LOG_DEBUG_ASN1,
                                                "ASN.1 problem: more than "
                                                "one CHOICE when encoding %s: "
                                                "%s and %s both present\n",
                                                entry->name,
                                                choice->name,
                                                list->name);
                                        return SC_ERROR_INVALID_ASN1_OBJECT;
                                }
                                choice = list;
                        }
                        list++;
                }
                if (choice == NULL)
                        goto no_object;
                return asn1_encode_entry(ctx, choice, obj, objlen, depth + 1);
        }

        if (entry->type != SC_ASN1_NULL && parm == NULL) {
                sc_debug(ctx, SC_LOG_DEBUG_ASN1, "unexpected parm == NULL\n");
                return SC_ERROR_INVALID_ASN1_OBJECT;
        }

        switch (entry->type) {
        case SC_ASN1_STRUCT:
